var t=132;var i=[{id:`cooking-132-01`,theoryId:132,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What is a primary purpose of controlled meat aging?`,ua:`Яка головна мета контрольованого витримування м’яса?`},explanation:{en:`Controlled enzyme activity and moisture changes affect eating quality.`,ua:`Контрольована активність ферментів і зміни вологості впливають на якість.`},options:[{id:`a`,text:{en:`Develop tenderness and flavor under controlled conditions`,ua:`Покращити ніжність та смак у контрольованих умовах`}},{id:`b`,text:{en:`Make spoiled meat safe again`,ua:`Зробити зіпсоване м’ясо безпечним`}},{id:`c`,text:{en:`Replace refrigeration with room temperature`,ua:`Замінити холодильник кімнатною температурою`}}],answer:{optionIds:[`a`]}},{id:`cooking-132-02`,theoryId:132,type:`true_false`,difficulty:`beginner`,safetyCritical:!0,question:{en:`An unpleasant spoilage smell should be ignored if meat has been labeled aged.`,ua:`Неприємний запах псування можна ігнорувати, якщо м’ясо позначене як витримане.`},explanation:{en:`Aging is not a remedy for spoilage and must occur under controlled hygiene and refrigeration.`,ua:`Витримування не усуває псування й потребує контролю гігієни та охолодження.`},answer:{value:!1}},{id:`cooking-132-03`,theoryId:132,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match observations to interpretations.`,ua:`Поєднайте ознаки м’яса з поясненнями.`},explanation:{en:`Safety assessment and culinary maturity are separate.`,ua:`Оцінка безпеки та кулінарної зрілості — різні речі.`},leftItems:[{id:`l1`,text:{en:`Controlled aging`,ua:`Контрольоване витримування`}},{id:`l2`,text:{en:`Persistent sour or putrid smell`,ua:`Стійкий кислий або гнильний запах`}},{id:`l3`,text:{en:`Correct cold chain`,ua:`Належний холодовий ланцюг`}}],rightItems:[{id:`r3`,text:{en:`Helps reduce microbial growth risk`,ua:`Допомагає зменшити ризик росту мікробів`}},{id:`r2`,text:{en:`Potential spoilage warning`,ua:`Можлива ознака псування`}},{id:`r1`,text:{en:`Enzymatic tenderization and flavor change`,ua:`Ферментативне розм’якшення й зміна смаку`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-132-04`,theoryId:132,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A raw steak package is leaking, warm and smells unpleasant. What is the responsible action?`,ua:`Упаковка сирого стейка протікає, тепла й має неприємний запах. Що робити?`},explanation:{en:`Packaging damage, temperature abuse and spoilage indicators warrant rejection.`,ua:`Пошкодження пакування, порушення температури та ознаки псування — підстави для відмови.`},options:[{id:`a`,text:{en:`Reject the product`,ua:`Відмовитися від продукту`}},{id:`b`,text:{en:`Mask the smell with spices`,ua:`Замаскувати запах спеціями`}},{id:`c`,text:{en:`Call it dry-aged and serve`,ua:`Назвати його витриманим і подати`}}],answer:{optionIds:[`a`]}},{id:`cooking-132-05`,theoryId:132,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which claim about aging is inaccurate?`,ua:`Яке твердження про витримування хибне?`},explanation:{en:`Warm uncontrolled holding can allow dangerous microbial growth.`,ua:`Неконтрольоване тримання в теплі створює ризик росту небезпечних мікроорганізмів.`},options:[{id:`a`,text:{en:`Temperature control matters`,ua:`Температурний контроль важливий`}},{id:`b`,text:{en:`Humidity can affect aging`,ua:`Вологість може впливати на витримування`}},{id:`c`,text:{en:`Leaving raw meat warm on a counter for days is proper aging`,ua:`Залишити сире м’ясо в теплі на кілька днів — належне витримування`}}],answer:{optionIds:[`c`]}}];var n={theoryId:132,exercises:i};export{n as default,i as exercises,t as theoryId};